<script lang="ts" module>
	import type { RxColor } from '$lib/registry/lib/color';
	export interface ColorPickerProps { value?: string; variant?:'base'|'compact'|'palette'|'ring'|'slider'|'swatches'; alpha?: boolean; swatches?: string[]; color?: RxColor; size?: 'lg' | 'default' | 'sm'; disabled?: boolean; open?:boolean; onValueChange?: (value: string) => void }
</script>
<script lang="ts">
	import { styleColor } from '$lib/registry/lib/color'; import { proximityGlow } from '$lib/registry/attachments/proximity-glow'; import { neighborLight } from '$lib/registry/attachments/neighbor-light'; import { parseColor, hsvToHex, type HsvColor } from './hsv';
	let { value = $bindable('#3366ff'), variant='base', alpha = false, swatches = [], color, size = 'default', disabled = false, open=$bindable(false), onValueChange }: ColorPickerProps = $props();
	let initial = parseColor(value) ?? { h: 220, s: .8, v: 1, a: 1 };
	let hsv = $state<HsvColor>(initial), textValue = $state(value), invalid = $state(false);
	const hex = $derived(hsvToHex(hsv, alpha)); const hueColor = $derived(hsvToHex({ h: hsv.h, s: 1, v: 1, a: 1 }));
	const attachGlow = $derived(proximityGlow({ radius: 200, disabled: () => disabled }));
	const attachNeighbor = $derived(neighborLight({ disabled: () => disabled }));
	$effect(() => { const next = parseColor(value, hsv.h); if (next && value.toLowerCase() !== hex) { hsv = next; textValue = hsvToHex(next, alpha); invalid = false; } });
	function commit(next: HsvColor) { hsv = next; const output = hsvToHex(next, alpha); value = output; textValue = output; invalid = false; onValueChange?.(output); }
	function pointer(node: HTMLElement, update: (x: number, y: number) => void) { const move = (event: PointerEvent) => { const rect = node.getBoundingClientRect(); update(Math.min(1, Math.max(0, (event.clientX - rect.left) / rect.width)), Math.min(1, Math.max(0, (event.clientY - rect.top) / rect.height))); }; const down = (event: PointerEvent) => { if (disabled) return; node.dataset.active='true';node.setPointerCapture(event.pointerId); move(event); }; const drag = (event: PointerEvent) => { if (node.hasPointerCapture(event.pointerId)) move(event); };const up=(event:PointerEvent)=>{node.dataset.active='false';node.releasePointerCapture?.(event.pointerId)}; node.addEventListener('pointerdown', down); node.addEventListener('pointermove', drag);node.addEventListener('pointerup',up);node.addEventListener('pointercancel',up); return () => { node.removeEventListener('pointerdown', down); node.removeEventListener('pointermove', drag);node.removeEventListener('pointerup',up);node.removeEventListener('pointercancel',up); }; }
	function key(event: KeyboardEvent, axis: 'h' | 's' | 'v' | 'a') { if (disabled || !['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)) return; event.preventDefault(); const direction = event.key === 'ArrowRight' || event.key === 'ArrowUp' ? 1 : -1; const amount = direction * (event.shiftKey ? 10 : 1); commit({ ...hsv, [axis]: axis === 'h' ? (hsv.h + amount + 360) % 360 : Math.min(1, Math.max(0, hsv[axis] + amount / 100)) }); }
	function textChange(event: Event) { textValue = (event.currentTarget as HTMLInputElement).value; const parsed = parseColor(textValue, hsv.h); if (!parsed) { invalid = true; return; } commit(parsed); }
</script>

{#snippet panel()}
	<div class="rx-color-picker__panel" data-rx-lamp {@attach attachGlow} {@attach attachNeighbor}>
	<span class="rx-color-picker__pointer-ring" aria-hidden="true"></span><span class="rx-color-picker__neighbor" aria-hidden="true"></span>
	<div class="rx-color-picker__area" data-active="false" aria-label="Saturation and brightness" role="slider" tabindex={disabled ? -1 : 0} aria-disabled={disabled} aria-valuemin="0" aria-valuemax="100" aria-valuenow={Math.round(hsv.s * 100)} aria-valuetext={`Saturation ${Math.round(hsv.s*100)}%, brightness ${Math.round(hsv.v*100)}%`} onkeydown={(e) => key(e, e.altKey ? 'v' : 's')} {@attach (node) => pointer(node, (x,y) => commit({...hsv,s:x,v:1-y}))}>
		<span class="rx-color-picker__area-knob" style={`left:${hsv.s*100}%;top:${(1-hsv.v)*100}%`}></span>
	</div>
	<div class="rx-color-picker__rail rx-color-picker__hue" data-active="false" style={`--hue-angle:${hsv.h}`} role="slider" aria-label="Hue" tabindex={disabled ? -1 : 0} aria-valuemin="0" aria-valuemax="359" aria-valuenow={Math.round(hsv.h)} aria-valuetext={`${Math.round(hsv.h)} degrees`} onkeydown={(e)=>key(e,'h')} {@attach (node) => pointer(node, (x,y) => commit({...hsv,h:variant==='ring' ? (Math.atan2(y-.5,x-.5)*180/Math.PI+90+360)%360 : x*359}))}><span style={`left:${hsv.h/359*100}%`}></span></div>
	{#if alpha}<div class="rx-color-picker__rail rx-color-picker__alpha" data-active="false" style={`--picked:${hsvToHex({...hsv,a:1})}`} role="slider" aria-label="Alpha" tabindex={disabled ? -1 : 0} aria-valuemin="0" aria-valuemax="100" aria-valuenow={Math.round(hsv.a*100)} aria-valuetext={`${Math.round(hsv.a*100)}% opacity`} onkeydown={(e)=>key(e,'a')} {@attach (node) => pointer(node, (x) => commit({...hsv,a:x}))}><span style={`left:${hsv.a*100}%`}></span></div>{/if}
	{#if swatches.length}<div class="rx-color-picker__swatches" aria-label="Color presets">{#each swatches as swatch}<button type="button" class:selected={swatch.toLowerCase()===hex.slice(0,7).toLowerCase()} disabled={disabled} aria-label={`Choose ${swatch}`} style={`background:${swatch}`} onclick={() => { const next=parseColor(swatch,hsv.h); if(next) commit(next); }}><span aria-hidden="true">✓</span></button>{/each}</div>{/if}
	<label class="rx-color-picker__input" class:rx-color-picker__input--invalid={invalid}><span class="rx-color-picker__preview" style={`background:${hex}`}></span><input aria-label="Color value" aria-invalid={invalid} disabled={disabled} value={textValue} oninput={textChange} />{#if invalid}<small role="alert">Enter a valid hex or RGB color.</small>{/if}</label>
	</div>
{/snippet}
<div class="rx-color-picker rx-color-picker--{size} rx-color-picker--{variant}" class:rx-color-picker--disabled={disabled} style={`${styleColor(color) ?? '--rx-color: var(--rx-primary)'}; --picked-hue:${hueColor}`} data-rx-lamp {@attach attachGlow} {@attach attachNeighbor}>
	{#if variant==='compact'}<button type="button" class="rx-color-picker__trigger" disabled={disabled} aria-expanded={open} onclick={()=>open=!open}><span class="rx-color-picker__trigger-ring" aria-hidden="true"></span><span style={`background:${hex}`}></span><b>{hex}</b><i aria-hidden="true">⌄</i></button>{#if open}{@render panel()}{/if}{:else}{@render panel()}{/if}
</div>
<style>
