(--rx-text)/.18);cursor:pointer;transition:transform 220ms cubic-bezier(.34,1.56,.64,1),box-shadow 200ms}.rx-color-picker__swatches button:hover{transform:translateY(-3px) scale(1.08)}.rx-color-picker__swatches button.selected{box-shadow:0 0 0 2px rgb(var(--rx-background)),0 0 0 4px rgb(var(--rx-color))}.rx-color-picker__swatches button span{color:#fff;text-shadow:0 1px 2px #000;opacity:0;transform:scale(.5);transition:opacity 200ms,transform 200ms}.rx-color-picker__swatches button.selected span{opacity:1;transform:scale(1)}.rx-color-picker__input{display:grid;grid-template-columns:auto 1fr;align-items:center;gap:.5rem}.rx-color-picker__input input{min-width:0;padding:.6rem .7rem;border:1px solid rgb(var(--rx-text)/.16);border-radius:calc(var(--rx-radius)*.65);background:transparent;color:rgb(var(--rx-text));font:inherit}.rx-color-picker__preview{width:1.8rem;height:1.8rem;border-radius:.45rem;border:1px solid rgb(var(--rx-text)/.15)}.rx-color-picker__input small{grid-column:1/-1;color:rgb(var(--rx-danger))}.rx-color-picker__input--invalid input{border-color:rgb(var(--rx-danger))}.rx-color-picker :focus-visible{outline:3px solid rgb(var(--rx-color)/.28);outline-offset:2px}
